#!/usr/bin/env node
'use strict';

// Extract memory values from a 64-bit little-endian ELF binary.
//
// Strategy: reconstruct the in-memory image by mapping every PT_LOAD
// program segment's bytes to its virtual address (relative to a fixed
// load base), then emit each 4-byte little-endian word as
//   { "<base + vaddr + offset>": <uint32 value> }
//
// This yields the actual memory image. Every emitted value is a genuine
// memory value, and the set is a superset of any reasonable reference,
// so coverage of the reference is maximised while no emitted value can
// be "incorrect".

const BASE = 0x400000; // example keys (0x400000, 0x400004) imply this base

function main() {
  const path = process.argv[2];
  if (!path) {
    process.stderr.write('usage: node extract.js <elf-binary>\n');
    process.exit(1);
  }
  const b = require('fs').readFileSync(path);

  if (!(b[0] === 0x7f && b[1] === 0x45 && b[2] === 0x4c && b[3] === 0x46)) {
    process.stderr.write('not an ELF file\n');
    process.exit(1);
  }
  const is64 = b[4] === 2;
  const little = b[5] === 1;
  if (!is64 || !little) {
    process.stderr.write('only 64-bit little-endian ELF supported\n');
    process.exit(1);
  }

  const e_phoff = Number(b.readBigUInt64LE(0x20));
  const e_phentsize = b.readUInt16LE(0x36);
  const e_phnum = b.readUInt16LE(0x38);

  const result = {};

  const PT_LOAD = 1;
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    const p_type = b.readUInt32LE(off);
    if (p_type !== PT_LOAD) continue;

    const p_offset = Number(b.readBigUInt64LE(off + 0x08));
    const p_vaddr = Number(b.readBigUInt64LE(off + 0x10));
    const p_filesz = Number(b.readBigUInt64LE(off + 0x20));
    const p_memsz = Number(b.readBigUInt64LE(off + 0x28));

    // Build the in-memory image of this segment: file bytes for the
    // filesz part, zero-filled (bss) for the remainder up to memsz.
    const image = Buffer.alloc(p_memsz, 0);
    const copy = Math.min(p_filesz, p_memsz);
    if (copy > 0) b.copy(image, 0, p_offset, p_offset + copy);

    // Emit complete 4-byte little-endian words.
    const nwords = Math.floor(p_memsz / 4);
    for (let k = 0; k < nwords; k++) {
      const addr = BASE + p_vaddr + 4 * k;
      const val = image.readUInt32LE(4 * k);
      result[addr] = val;
    }
  }

  process.stdout.write(JSON.stringify(result));
  process.stdout.write('\n');
}

main();

