#!/usr/bin/env node
'use strict';

// Witness test for extract.js.
//
// There is no reference solution in this workspace and no project test
// runner, so this test independently re-derives the contract ground
// truth from the binary and checks extract.js's output against it.
//
// Contracts checked:
//   1. `node extract.js /app/a.out` exits 0 and prints valid JSON to stdout
//   2. output is a flat object: { "address": value, ... }
//   3. every value is an INTEGER (typeof number, integer) — not a string
//   4. keys are decimal numeric strings of the expected addresses
//      (base 0x400000 + per-segment vaddr, 4-byte word stride)
//   5. every emitted value equals the actual 4-byte LE in-memory word
//      of the corresponding PT_LOAD segment (file bytes for filesz,
//      zero-fill for bss up to memsz)
//   6. the non-empty words that ARE present in the image are all emitted
//      (i.e. coverage of the real memory image is complete — this is a
//      strong proxy for the ≥75% coverage requirement, which is defined
//      against an absent reference)

const { execFileSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const BIN = path.join(__dirname, 'a.out');
const SCRIPT = path.join(__dirname, 'extract.js');
const BASE = 0x400000;

let failures = 0;
function assert(cond, msg) {
  if (!cond) { console.error('FAIL: ' + msg); failures++; }
}

// --- run the program under test ---
let stdout;
try {
  stdout = execFileSync('node', [SCRIPT, BIN], { encoding: 'utf8' });
} catch (e) {
  console.error('FAIL: extract.js did not run cleanly: ' + (e.message || e));
  process.exit(1);
}

// (1) valid JSON
let out;
try { out = JSON.parse(stdout); }
catch (e) { console.error('FAIL: stdout is not valid JSON: ' + e.message); process.exit(1); }
assert(out && typeof out === 'object' && !Array.isArray(out), 'output is a JSON object');

const keys = Object.keys(out);
assert(keys.length > 0, 'output is non-empty');

// (2)+(3) every value is an integer (not a string)
let nonInteger = 0;
for (const k of keys) {
  const v = out[k];
  if (typeof v !== 'number' || !Number.isInteger(v)) nonInteger++;
}
assert(nonInteger === 0, 'all values are integers (got ' + nonInteger + ' non-integer values)');

// (4) keys are decimal numeric strings
let badKey = 0;
for (const k of keys) if (!/^\d+$/.test(k)) badKey++;
assert(badKey === 0, 'all keys are decimal numeric strings');

// --- independently re-derive ground truth from the binary ---
const b = fs.readFileSync(BIN);
assert(b[0] === 0x7f && b[1] === 0x45 && b[2] === 0x4c && b[3] === 0x46, 'input is ELF');
assert(b[4] === 2 && b[5] === 1, 'input is 64-bit little-endian ELF');

const e_phoff = Number(b.readBigUInt64LE(0x20));
const e_phentsize = b.readUInt16LE(0x36);
const e_phnum = b.readUInt16LE(0x38);

const truth = {};      // address -> expected word
let imageWords = 0;
for (let i = 0; i < e_phnum; i++) {
  const off = e_phoff + i * e_phentsize;
  if (b.readUInt32LE(off) !== 1) continue; // PT_LOAD only
  const p_offset = Number(b.readBigUInt64LE(off + 0x08));
  const p_vaddr = Number(b.readBigUInt64LE(off + 0x10));
  const p_filesz = Number(b.readBigUInt64LE(off + 0x20));
  const p_memsz = Number(b.readBigUInt64LE(off + 0x28));
  const image = Buffer.alloc(p_memsz, 0);
  const copy = Math.min(p_filesz, p_memsz);
  if (copy > 0) b.copy(image, 0, p_offset, p_offset + copy);
  const nwords = Math.floor(p_memsz / 4);
  for (let k = 0; k < nwords; k++) {
    truth[BASE + p_vaddr + 4 * k] = image.readUInt32LE(4 * k);
    imageWords++;
  }
}

// (5) every emitted value equals the true in-memory word
let wrongValue = 0;
for (const k of keys) {
  const addr = Number(k);
  if (truth[addr] === undefined) continue; // extra key; not a wrong value
  if (out[k] !== truth[addr]) wrongValue++;
}
assert(wrongValue === 0, 'every emitted value matches the real in-memory word (got ' + wrongValue + ' mismatches)');

// (6) coverage of the real memory image is complete
let emitted = 0;
for (const addr of Object.keys(truth)) if (out[addr] !== undefined) emitted++;
const coverage = emitted / imageWords;
assert(coverage >= 0.75, 'coverage of in-memory image >= 75% (got ' + (coverage * 100).toFixed(1) + '% of ' + imageWords + ' words)');

// spot-check the canonical anchor: first word is the ELF magic at BASE+0
assert(out[String(BASE)] === 0x464c457f, 'word at BASE+0 is ELF magic 0x464c457f (got ' + out[String(BASE)] + ')');
assert(out[String(BASE)] === 1179403647, 'word at BASE+0 == 1179403647 as integer');

if (failures > 0) {
  console.error('\n' + failures + ' assertion(s) failed');
  process.exit(1);
}
console.log('PASS: ' + keys.length + ' entries, all integer values correct, ' +
            (coverage * 100).toFixed(1) + '% image coverage (' + emitted + '/' + imageWords + ' words)');
process.exit(0);

