// Guard the deliverable's existence BEFORE invoking it: on a baseline that
// lacks extract.js we want a clean assertion failure, not a Node
// "Cannot find module" error (which a harness can mistake for a build error).
if (!fs.existsSync(SCRIPT)) {
  console.error('FAIL: deliverable extract.js does not exist (no program output to check)');
  process.exit(1);
}
