  stdout = execFileSync('node', [SCRIPT, BIN], { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
} catch (e) {
  // Surface a clean assertion-style message; do NOT propagate any child
  // module-resolution trace.
  console.error('FAIL: extract.js exited non-zero / produced no JSON output');
  process.exit(1);
}

